import { createElement } from "react";
import { ParamRow, SliderParamInput, useParamHelpers, registerNodeKind, baseNode, pin, runWorkerJob, loadSignal } from "@merlin/plugin-api";

// Canvas 0.21 emits raw worker progress before the Mesh UI reformats the stage.
let notice;
let noticeExecution;
let noticeTimer;

function clearVerificationNotice() {
  clearTimeout(noticeTimer);
  notice?.remove();
  notice = undefined;
  noticeExecution = undefined;
}

function showVerificationCode({detail}) {
  const execution = detail?.execution_id;
  if (!execution || typeof detail.status !== "string") return;
  const match = /^Rodin verification code: ([A-Za-z0-9-]{4,32}) \| Sign in at https:\/\//.exec(detail.status);
  if (!match) {
    if (noticeExecution === execution) clearVerificationNotice();
    return;
  }
  if (!notice) {
    notice = document.createElement("aside");
    notice.setAttribute("role", "status");
    notice.style.cssText = "position:fixed;top:16px;left:50%;transform:translateX(-50%);z-index:2147483647;background:#202428;color:#fff;padding:12px 20px;border:1px solid #608580;border-radius:8px;font:16px sans-serif;user-select:text";
    document.body.append(notice);
  }
  noticeExecution = execution;
  const message = `Rodin sign-in · ${match[1]} · Confirm this code on the Hyper3D page.`;
  if (notice.textContent !== message) notice.textContent = message;
  clearTimeout(noticeTimer);
  noticeTimer = setTimeout(clearVerificationNotice, 60000);
}

window.addEventListener("services-progress", showVerificationCode, {signal: loadSignal});
loadSignal.addEventListener("abort", clearVerificationNotice, {once: true});

// Refreshed by publishing/sync_controls.py from the MCP input schema.
const bangStrength = {"type": "slider", "key": "strength", "label": "Strength", "min": 1, "max": 12, "step": 1, "default": 5};

function BangEditor({node, canvasId}) {
  const {setParam, readOnly} = useParamHelpers(canvasId, node.id, node.pins);
  const {key, label, min, max, step} = bangStrength;
  return createElement(ParamRow, {label, paramKey: key},
    createElement("fieldset", {disabled: readOnly, style: {border: 0, padding: 0, margin: 0}},
      createElement(SliderParamInput, {
        value: node.params[key] ?? bangStrength.default, ariaLabel: label,
        min, max, sliderMin: min, sliderMax: max, step, onChange: value => setParam(key, value)
      })));
}

for (const op of ["bang", "login", "status"]) {
  const kind = "rodinCanvas." + op;
  const isMesh = op === "bang";
  const label = { bang: "Rodin BANG", login: "Rodin Sign In", status: "Rodin Account Status" }[op];
  const description = {
    bang: "Split a model generated by this Rodin extension into parts.",
    login: "Sign in to Hyper3D in your browser with a device code.",
    status: "Check whether this extension has a saved Rodin session."
  }[op];
  registerNodeKind({
    kind,
    meta: { label, color: "#287c7c", category: isMesh ? "Geometry" : "Custom", description },
    ...(isMesh ? {editor: BangEditor} : {}),
    factory: (pos = {x: 0, y: 0}) => baseNode(kind, label, pos, isMesh
      ? [pin("source", "mesh", "input"), pin("mesh", "mesh", "output")]
      : [pin("text", "text", "output")], isMesh ? {strength: bangStrength.default} : {}),
    traits: { isGeneration: true },
    adapter: {
      handles: [kind],
      async run({ node, inputs, signal, onProgress, canvasId, requireReviewedModels, live }) {
        if (live) throw new Error("Run this Rodin card once, outside the live loop.");
        if (isMesh && !inputs.source) throw new Error("Connect a mesh generated by this Rodin extension.");
        const result = await runWorkerJob("rodin-canvas-" + op,
          { inputs: isMesh ? {mesh: inputs.source} : {}, params: isMesh ? {strength: node.params.strength ?? bangStrength.default} : node.params },
          { signal, onProgress, canvasId, nodeId: node.id, requireReviewedModels });
        return isMesh ? { outputFilePaths: {"output.glb": result.mesh} } : { outputValues: {text: result.text} };
      }
    }
  });
}
